const r=$input.first().json;if(r.statusCode!==200){throw new Error('Read failed: '+r.statusCode+' '+JSON.stringify(r.body).slice(0,300));}
const b=r.body||{};if(b.meta&&b.meta.hasMore){throw new Error('Glossary has more than 500 terms; dedupe incomplete, nothing written.');}
const existing=(b.data||[]);const have={};for(const t of existing){have[String(t.term).trim().toLowerCase()]=t;}
const T='realchecker';
const C=[
{term:'RealChecker',description:'Product name. Never translate or split.',caseSensitive:true,translatable:false},
{term:'Google Pay',description:'Payment method shown on the RealChecker checkout.',caseSensitive:true,translatable:false},
{term:'Google',description:'As in the "Continue with Google" sign-up button.',caseSensitive:true,translatable:false},
{term:'Visa',description:'Card brand logo on the checkout.',caseSensitive:true,translatable:false},
{term:'Mastercard',description:'Card brand logo on the checkout.',caseSensitive:true,translatable:false},
{term:'American Express',description:'Card brand logo on the checkout.',caseSensitive:true,translatable:false},
{term:'Norton',description:'Trust badge on the checkout.',caseSensitive:true,translatable:false},
{term:'Checker-90',description:'Promo code. Must never be translated.',caseSensitive:true,translatable:false},
{term:'NHTSA',description:'National Highway Traffic Safety Administration (US). Source of safety recall data.',caseSensitive:true,translatable:false},
{term:'DPPA',description:"Driver's Privacy Protection Act (US). Mentioned in the ownership history section.",caseSensitive:true,translatable:false},
{term:'VIN',description:'Vehicle Identification Number, the 17-character vehicle ID. Some markets use their own acronym; decide per language whether to keep "VIN".',caseSensitive:true,translatable:true},
{term:'Vehicle Identification Number',description:'Full form of VIN, the 17-character vehicle ID.',caseSensitive:false,translatable:true},
{term:'VIN lookup',description:"The product's core action and tool name.",caseSensitive:false,translatable:true},
{term:'VIN check',description:'Same as VIN lookup; the check run on a VIN.',caseSensitive:false,translatable:true},
{term:'Vehicle history report',description:'The paid deliverable; the UI often shortens it to "report".',caseSensitive:false,translatable:true},
{term:'Verified records',description:'Badge label on the loader and summary pages.',caseSensitive:false,translatable:true}
];
const add=[];const skipped=[];for(const c of C){if(have[c.term.toLowerCase()]){skipped.push(c.term);continue;}add.push(Object.assign({forbidden:false,tags:[T]},c));}
return [{json:{existing_count:existing.length,add_count:add.length,skipped:skipped,body:{terms:add}}}];
